export type CardType = "summary" | "detail" | "experimental";

export function renderCard(type: CardType) {
  switch (type) {
    case "summary":
      return "Summary card";
    case "detail":
      return "Detail card";
    case "experimental":
      return "Experimental card";
  }
}

edits.newText:
export type CardType = "summary" | "detail";

export function renderCard(type: CardType) {
  switch (type) {
    case "summary":
      return "Summary card";
    case "detail":
      return "Detail card";
  }
}

